// @tailwind base;
@tailwind components;
@tailwind utilities;

/* Your custom styles below */

@import "assets/layout/styles/layout/layout.scss";
@import "assets/layout/styles/theme/lara-light-teal/theme.css";

@import "primeng/resources/primeng.css";
@import "primeicons/primeicons.css";

@import "../node_modules/primeflex/primeflex.css";

@import "assets/demo/styles/flags/flags.css";
@import "assets/demo/styles/badges.scss";
@import "assets/demo/styles/code.scss";

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: "Roboto", sans-serif;
  background-color: #fafafa;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

/* Material Design 樣式覆寫 */
.mat-mdc-form-field {
  width: 100%;
}

.mat-mdc-card {
  margin-bottom: 16px;
}

/* 拖拽樣式改進 */
.cdk-drag-handle {
  cursor: move;
}

.cdk-drop-list {
  min-height: 60px;
}

.cdk-drag-placeholder {
  opacity: 0.3;
  background: #ddd;
  border: 2px dashed #999;
  margin: 8px 0;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #999;
}

.cdk-drag-placeholder::before {
  content: "";
}

/* 響應式設計 */
@media (max-width: 1200px) {
  .editor-container {
    grid-template-columns: 200px 1fr;
  }

  .preview-area {
    display: none;
  }
}

@media (max-width: 768px) {
  .editor-container {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }

  .sidebar {
    padding: 8px;
    max-height: 200px;
    overflow-y: auto;
  }

  .element-list {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .element-item {
    flex: 1;
    min-width: 120px;
    padding: 8px;
    font-size: 12px;
  }
}
